const TZ = 'Europe/Berlin'
const LOCALE = 'de-DE'

function formatDateDE(dateKey: string) {
  // dateKey: YYYY-MM-DD
  const [y, m, d] = dateKey.split('-').map(Number)
  const dt = new Date(Date.UTC(y, m - 1, d))
  return new Intl.DateTimeFormat(LOCALE, {
    timeZone: TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(dt)
}

